import express from 'express';
let hitung = 0;
function catat(req, res, next) {
  res.on('finish', () => console.log(req.method, req.url, res.statusCode));
  next();
}
function nomorAntrean(req, res, next) {
  hitung++;
  req.nomor = hitung;
  next();
}
const app = express();
app.use(catat);
app.use(nomorAntrean);
app.get('/menu', (req, res) => res.json({ nomor: req.nomor }));
const server = app.listen(3000);
await fetch('http://localhost:3000/menu');
await fetch('http://localhost:3000/kasir');
console.log(await (await fetch('http://localhost:3000/menu')).json());
server.close();

