import express from 'express';
const app = express();
app.use((req, res, next) => {
  res.set('X-Toko', 'Sari');
  next();
});
app.get('/', (req, res) => res.send('ok'));
const server = app.listen(3000);
const r = await fetch('http://localhost:3000/');
console.log(r.headers.get('x-toko'));
server.close();
